def transform(grid):
    grid = np.array(grid)
    # colour pairing read off the train pairs; it is an involution (a <-> b)
    pairs = [(1, 5), (2, 6), (3, 4), (8, 9)]
    table = {}
    for a, b in pairs:
        table[a] = b
        table[b] = a

    out = grid.copy()
    # process each distinct colour in reading order of first appearance
    seen = []
    for v in grid.flatten():
        if v not in seen:
            seen.append(v)
    for c in seen:
        c = int(c)
        if c in table:
            out[grid == c] = table[c]
            emit(out.copy(), f"Recolour every cell of colour {c} to its partner colour {table[c]}")
    emit(out.copy(), "All colours swapped to their partner colours; final result")
    return out
